"""ORD_LINE renumbering migration for Meridian CRM 4.2."""

from decimal import Decimal
from typing import Any


def _numeric_line_no(value: Any) -> Decimal:
    """Coerce a legacy LINE_NO to its numeric comparison value."""
    if value == "":
        return Decimal(0)
    return Decimal(str(value))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted rows and renumber surviving lines per order."""
    surviving = [
        (index, dict(row))
        for index, row in enumerate(lines)
        if row.get("DEL_FLG", "") != "Y"
    ]

    surviving.sort(
        key=lambda item: (
            str(item[1].get("ORD_ID", "")),
            _numeric_line_no(item[1].get("LINE_NO", "")),
            item[0],
        )
    )

    result: list[dict] = []
    current_order: str | None = None
    next_line_no = 0

    for _, row in surviving:
        order_id = str(row.get("ORD_ID", ""))
        if current_order != order_id:
            current_order = order_id
            next_line_no = 1
        else:
            next_line_no += 1

        row["LINE_NO"] = next_line_no
        result.append(row)

    return result
